parameters.jsCode:
// Weekly payment run: approved, unpaid supplier bills that are overdue or due within the next DAYS_AHEAD days,
// grouped by currency, as one HTML email plus the list of sheet rows to mark as scheduled.
const DAYS_AHEAD = 7;
const MAX_ROWS = 60;

const now = new Date();
const todayUtc = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate());
const runId = 'RUN-' + new Date(todayUtc).toISOString().slice(0, 10);
const toDate = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return new Date(Date.UTC(1899, 11, 30) + Math.round(v) * 86400000); // Google Sheets serial date
  const s = String(v).trim();
  const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (iso) return new Date(Date.UTC(+iso[1], +iso[2] - 1, +iso[3]));
  const eu = s.match(/^(\d{1,2})[./](\d{1,2})[./](\d{4})$/); // dd.mm.yyyy or dd/mm/yyyy
  if (eu) return new Date(Date.UTC(+eu[3], +eu[2] - 1, +eu[1]));
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
};
const toNumber = (v) => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').replace(/[^\d.,-]/g, '');
  if (/^-?\d{1,3}(\.\d{3})+(,\d{1,2})?$/.test(s)) s = s.replace(/\./g, ''); // 1.250,00 -> 1250,00
  const n = Number(s.replace(/,(\d{1,2})$/, '.$1').replace(/,/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const money = (n) => (Math.round(n * 100) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const isoDate = (d) => d.toISOString().slice(0, 10);

const due = [];
for (const { json: r } of $input.all()) {
  if (!r || r.InvoiceNumber === undefined || String(r.InvoiceNumber).trim() === '') continue;
  if (!/^\s*approved\s*$/i.test(String(r.Status ?? ''))) continue;
  if (String(r.PaidDate ?? '').trim() !== '') continue;
  const d = toDate(r.DueDate);
  const amount = Math.round(toNumber(r.Amount) * 100) / 100;
  if (amount <= 0) continue;
  const daysToDue = d ? Math.round((d.getTime() - todayUtc) / 86400000) : 0; // no due date = pay now
  if (daysToDue > DAYS_AHEAD) continue;
  due.push({
    row: r.row_number, vendor: String(r.Vendor ?? '').trim(), number: String(r.InvoiceNumber).trim(), due: d ? isoDate(d) : '(no due date)',
    daysToDue, amount, currency: String(r.Currency ?? '').trim().toUpperCase() || '?', reference: String(r.PaymentReference ?? '').trim(),
    alreadyScheduled: String(r.PaymentRun ?? '').trim(),
  });
}
due.sort((a, b) => a.daysToDue - b.daysToDue || b.amount - a.amount);

const totals = {};
for (const b of due) totals[b.currency] = (totals[b.currency] || 0) + b.amount;
const fmtTotals = (t) => Object.keys(t).sort().map(c => money(t[c]) + ' ' + c).join(', ') || '-';
const asOf = isoDate(new Date(todayUtc));
const overdue = due.filter(b => b.daysToDue < 0);

if (!due.length) {
  return [{ json: { run_id: runId, subject: 'Payment run ' + asOf + ': nothing due', html: '<p>No approved supplier bills are due within the next ' + DAYS_AHEAD + ' days as of ' + asOf + '.</p>', bill_count: 0, overdue_count: 0, totals: {}, rows: [] } }];
}
const rows = due.slice(0, MAX_ROWS).map(b => '<tr' + (b.daysToDue < 0 ? ' style="background:#fff3f3"' : '') + '><td>' + esc(b.vendor) + '</td><td>' + esc(b.number) + '</td><td>' + esc(b.due) + '</td>' +
  '<td style="text-align:right">' + (b.daysToDue < 0 ? 'overdue ' + (-b.daysToDue) + ' d' : 'in ' + b.daysToDue + ' d') + '</td><td style="text-align:right">' + money(b.amount) + ' ' + esc(b.currency) + '</td><td>' + esc(b.reference || '-') + '</td>' +
  '<td>' + (b.alreadyScheduled ? 'in ' + esc(b.alreadyScheduled) : 'new') + '</td></tr>').join('');
const html = '<h2>Payment run ' + esc(runId) + '</h2>' +
  '<p><b>' + due.length + '</b> approved bill(s) due by ' + isoDate(new Date(todayUtc + DAYS_AHEAD * 86400000)) + (overdue.length ? ', <b style="color:#b00">' + overdue.length + ' already overdue</b>' : '') + '. Total to pay: <b>' + esc(fmtTotals(totals)) + '</b></p>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Vendor</th><th>Invoice</th><th>Due</th><th>When</th><th>Amount</th><th>Pay to / reference</th><th>Run</th></tr>' + rows + '</table>' +
  (due.length > MAX_ROWS ? '<p>Showing the first ' + MAX_ROWS + ' of ' + due.length + ' bills.</p>' : '') +
  '<p style="color:#666">Generated by the n8n supplier invoice workflow. Rows are marked with this run id in the PaymentRun column; fill in PaidDate once the transfer is done.</p>';

return [{ json: {
  run_id: runId,
  subject: 'Payment run ' + asOf + ': ' + due.length + ' bill(s), ' + fmtTotals(totals) + (overdue.length ? ' (' + overdue.length + ' overdue)' : ''),
  html, bill_count: due.length, overdue_count: overdue.length, totals,
  rows: due.map(b => ({ row_number: b.row, run_id: runId, invoice: b.number, vendor: b.vendor })),
} }];
